public static int laengsterAnstieg(int[] r) {
    if (r.length == 0) {
        return 0;
    }
    int beste = 1;
    int aktuell = 1;   // → Tabellenzeile (Startwerte)
    for (int i = 1; i < r.length; i++) {
        if (r[i] > r[i - 1]) {
            aktuell++;
            if (aktuell > beste) {
                beste = aktuell;
            }
        } else {
            aktuell = 1;
        }   // → Tabellenzeile
    }
    return beste;
}

public static double prozentBestanden(int[] punkte, int grenze) {
    if (punkte.length == 0) {
        return 0.0;
    }
    int anzahl = 0;
    for (int p : punkte) {
        if (p > grenze) {
            anzahl++;
        }
    }
    return anzahl / punkte.length * 100;
}

